const USERS = new Map([
  [1, { id: 1, name: 'Ada' }],
  [2, { id: 2, name: 'Grace' }],
]);

export function fetchUserData(id) {
  const user = USERS.get(id);
  if (!user) throw new Error(`no user ${id}`);
  return { ...user };
}

export const lines = [];

export function logLine(line) {
  lines.push(line);
}

import { fetchUserData } from './api.js';
import { logLine } from './log.js';

export function profileSummary(id) {
  const user = fetchUserData(id);
  logLine(`fetchUserData resolved user ${user.id}`);
  return `${user.name} (#${user.id})`;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { fetchUserData } from '../src/index.js';
import { lines } from '../src/log.js';
import { profileSummary } from '../src/profile.js';

test('profileSummary renders the user line', () => {
  assert.equal(profileSummary(1), 'Ada (#1)');
});

test('profileSummary logs the lookup', () => {
  profileSummary(2);
  assert.ok(lines.some((line) => line.includes('resolved user 2')));
});

test('the re-export serves the same function', () => {
  assert.equal(fetchUserData(1).name, 'Ada');
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();

// 1) Residual scan: zero mentions of the old name outside the excluded
//    history (CHANGELOG.md), the briefing material (source/), and
//    harness-owned files.
const SKIP_FILES = new Set(['CHANGELOG.md', 'task-notes.md', 'task-graph.md', 'tests/verify-sweep.mjs']);
const SKIP_DIRS = new Set(['node_modules', 'source']);
const hits = [];
function scan(dir) {
  for (const entry of readdirSync(dir)) {
    if (entry.startsWith('.')) continue;
    const full = join(dir, entry);
    const rel = relative(root, full).split('\\').join('/');
    const stat = statSync(full);
    if (stat.isDirectory()) {
      if (SKIP_DIRS.has(entry)) continue;
      scan(full);
      continue;
    }
    if (SKIP_FILES.has(rel)) continue;
    if (!/\.(js|mjs|cjs|json|md|txt)$/.test(entry)) continue;
    if (/\bfetchUserData\b/.test(readFileSync(full, 'utf8'))) hits.push(rel);
  }
}
scan(root);
assert.deepEqual(hits, [], `the old name survives outside the exclusions in: ${hits.join(', ')}`);
console.log('CODEMOD_ORACLE residual scan clean');

// 2) Every site behaves under the new name, including the tricky ones.
const api = await import(pathToFileURL(join(root, 'src/api.js')).href);
assert.equal(typeof api.loadUser, 'function', 'src/api.js must export loadUser');
assert.equal(api.fetchUserData, undefined, 'src/api.js still exports the old name');
const index = await import(pathToFileURL(join(root, 'src/index.js')).href);
assert.equal(typeof index.loadUser, 'function', 'src/index.js must re-export loadUser');
assert.equal(index.fetchUserData, undefined, 'src/index.js still re-exports the old name');
assert.equal(index.loadUser(1).name, 'Ada', 'the re-exported loadUser must return the same records');
const { profileSummary } = await import(pathToFileURL(join(root, 'src/profile.js')).href);
const { lines } = await import(pathToFileURL(join(root, 'src/log.js')).href);
assert.equal(profileSummary(1), 'Ada (#1)', 'profileSummary behavior must be unchanged');
assert.ok(
  lines.some((line) => line.includes('loadUser resolved user 1')),
  'the log string must follow the rename',
);
assert.ok(
  !lines.some((line) => line.includes('fetchUserData')),
  'a log string still mentions the old name',
);
console.log('CODEMOD_ORACLE behavior ok');

// 3) History kept: the excluded changelog still records the old name.
assert.ok(
  /\bfetchUserData\b/.test(readFileSync(join(root, 'CHANGELOG.md'), 'utf8')),
  'CHANGELOG.md must keep the historical name',
);
console.log('CODEMOD_ORACLE history kept');

// 4) The suite is green after the sweep, and the seeded test file survives.
readFileSync(join(root, 'tests/profile.test.mjs'));
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(root), 0, 'the suite must be green after the sweep');
console.log('CODEMOD_ORACLE suite green');
console.log('CODEMOD_ORACLE done');
